#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
# Regression test of libfish_container_shim.so: a program pushes 3 Imu and 2 TwistWithCovarianceStamped messages into
# std::deque members, clears them, and must compute the same values with and without the shim; with the shim and
# FISH_CONTAINER_SHIM_DEBUG=1 the hook must report 5 pushes (kind 1) and 2 clears (kind 3) with the right stamps.
# usage: test_container_shim.sh <libfish_container_shim.so>
set -u
SHIM=${1:?shim}; D=$(mktemp -d)
cat > $D/node.cpp <<'CPP'
// the node logic lives in a SHARED LIBRARY, like a ROS 2 component: its calls to the deque slow paths go through the
// PLT and can be interposed (a standalone executable binds its own instantiations directly — no interposition)
#include <deque>
#include <sensor_msgs/msg/imu.hpp>
#include <geometry_msgs/msg/twist_with_covariance_stamped.hpp>
struct Node { std::deque<sensor_msgs::msg::Imu> gyro; std::deque<geometry_msgs::msg::TwistWithCovarianceStamped> twist; };
extern "C" double fish_test_run(unsigned long * sizes) {
  Node n; double acc = 0;
  for (int i = 0; i < 3; i++) { sensor_msgs::msg::Imu m; m.header.stamp.sec = 100 + i; m.header.stamp.nanosec = 7; m.angular_velocity.z = i; n.gyro.push_back(m); }
  for (int i = 0; i < 2; i++) { geometry_msgs::msg::TwistWithCovarianceStamped t; t.header.stamp.sec = 200 + i; t.twist.twist.linear.x = 2.0 * i; n.twist.push_back(t); }
  for (auto & g : n.gyro) acc += g.angular_velocity.z;
  for (auto & t : n.twist) acc += t.twist.twist.linear.x;
  n.gyro.clear(); n.twist.clear();
  sizes[0] = n.gyro.size(); sizes[1] = n.twist.size();
  return acc;
}
CPP
cat > $D/t.cpp <<'CPP'
// the library is dlopen-ed RTLD_LOCAL like a ROS 2 component plugin: its symbols are invisible to RTLD_NEXT
#include <cstdio>
#include <dlfcn.h>
int main(int argc, char ** argv) {
  void * h = dlopen(argv[1], RTLD_NOW | RTLD_LOCAL); if (!h) { fprintf(stderr, "dlopen: %s\n", dlerror()); return 2; }
  double (*run)(unsigned long *) = (double (*)(unsigned long *))dlsym(h, "fish_test_run");
  unsigned long s[2]; double acc = run(s); printf("RESULT %.1f %lu %lu\n", acc, s[0], s[1]); return 0; }
CPP
set +u; source /opt/ros/humble/setup.bash 2>/dev/null; [ -f /opt/autoware/setup.bash ] && source /opt/autoware/setup.bash
# the shim links the OVERLAY's libtracetools (the only one with fish_container_op): it must come first on the library path
[ -f /root/trace_overlay_ws/install/setup.bash ] && source /root/trace_overlay_ws/install/setup.bash; set -u
INC=""; for p in sensor_msgs geometry_msgs std_msgs builtin_interfaces rosidl_runtime_cpp rosidl_runtime_c rosidl_typesupport_interface rcutils rcpputils; do INC="$INC -I/opt/ros/humble/include/$p"; done
# (not include/*: the dds/ and idl/ directories there shadow <features.h> / <string.h>)
g++ -O2 -fno-inline -std=c++17 -fPIC -shared -o $D/libtestnode.so $D/node.cpp $INC 2>$D/cc.err && g++ -O2 -std=c++17 -o $D/t $D/t.cpp -ldl 2>>$D/cc.err || { echo "SHIM_TEST_FAIL container: test build ($(grep -m1 "error" $D/cc.err | cut -c1-160))"; exit 1; }
A=$($D/t $D/libtestnode.so); B2=$(LD_PRELOAD=$SHIM FISH_CONTAINER_SHIM_DEBUG=1 $D/t $D/libtestnode.so 2>$D/dbg)
[ "$A" = "$B2" ] || { echo "SHIM_TEST_FAIL container: result differs ($A vs $B2)"; exit 1; }
P=$(grep -c "kind=1 " $D/dbg); E=$(grep -c "kind=3 " $D/dbg); ST=$(grep -o "w0=[0-9a-f]*" $D/dbg | head -1)
# the test exercises deque<Imu> / deque<TwistWithCovarianceStamped>; an image whose libraries never instantiate them has no
# such symbol in the shim (the scan is per image) — then only "same result, no crash" can be checked
TAB="$(dirname "$SHIM")/fish_container_shim.json"
if [ -f "$TAB" ] && ! grep -q "sensor_msgs::msg::Imu_" "$TAB"; then
  echo "SHIM_TEST_OK container: image has no deque<Imu> instantiation ($(python3 -c "import json;print(len(json.load(open('$TAB'))))" 2>/dev/null) symbols interposed); result identical with the shim preloaded; $A"; exit 0
fi
if [ "$P" = 5 ] && [ "$E" = 2 ] && [ "$ST" = "w0=700000064" ]; then echo "SHIM_TEST_OK container: 5 pushes, 2 clears, stamp of the first Imu read (sec 100 nanosec 7); $A"; else echo "SHIM_TEST_FAIL container: pushes=$P clears=$E first=$ST"; head -3 $D/dbg; exit 1; fi
